<?phpnamespace app\api\controller;use app\api\model\Page as PageModel;use app\api\model\Setting;/** * 小程序 */class Applet extends Controller{    /**     * 小程序基础信息     */    public function base()    {        $page = PageModel::getHome()['page_data']['array']; //获取DIY页面数据		$applet['navbar'] = $page['page'];        $applet['tabbar'] = $page['tabbar'];                $system = config('app.hemaphp.system');        $applet['system'] = $system;        $config = get_addons_config($system);//获取插件版本号        $applet['copyright'] = $config['copyright'];        $applet['version'] = get_addons_info($system)['version'];//获取插件版本号                $applet['shop'] = Setting::getItem('shop');        $applet['theme'] = 'default';//风格        $applet['is_arraign'] = false;//是否提审？        return $this->renderSuccess($applet);    }}